    }

    /* ↓ 自己写：
       ① 两两都比一遍，一共多少下
       ② 一路砍半，每层过整本，一共多少下 */
    long long pairs = 0;
    long long layers = 0;

    printf("两两比过：%lld 下\n", pairs);
    printf("层层砍半：%lld 下\n", layers);
